#!/usr/bin/env python3
import base64, subprocess, zlib
BASELINE = "6e7ceb2be9ce48c1ba96aed49d89794b58128194"
FILES = [
    "app/src/main/java/com/gree1d/reappzuku/core/ShellManager.java",
    "app/src/main/java/com/gree1d/reappzuku/core/App.java",
    "app/src/main/java/com/gree1d/reappzuku/ui/MainActivity.java",
    "app/src/main/java/com/gree1d/reappzuku/manager/BackgroundAppManager.java",
]
subprocess.run(["git", "checkout", BASELINE, "--", *FILES], check=True)
patch = zlib.decompress(base64.b64decode(""))
subprocess.run(["git", "apply", "--whitespace=error", "-"], input=patch, check=True)
print("Restored authoritative source and applied phase-2 readiness diff")
